!function(){"use strict";var e=document.querySelectorAll(".category");e.forEach(function(t){t.addEventListener("click",function(){e.forEach(function(e){e.classList.remove("category--active")}),t.classList.add("category--active")})});var t=document.querySelector(".map__locate");t&&t.addEventListener("click",function(){navigator.geolocation?navigator.geolocation.getCurrentPosition(function(e){console.log("Широта:",e.coords.latitude),console.log("Долгота:",e.coords.longitude)},function(e){alert("Не удалось определить местоположение: "+e.message)}):alert("Геолокация не поддерживается вашим браузером")});var o=document.querySelectorAll(".header__fav, .btn--outline");o.forEach(function(e){e.addEventListener("click",function(){var t="true"===e.dataset.fav;e.dataset.fav=t?"false":"true",e.textContent=t?"♡":"♥"})})}();